import{_ as i,o as s,c as r,aO as e}from"./chunks/framework.BFrk9dwu.js";const o="/recipes/koushui-chicken.jpg",a="/recipes/koushui-chicken/top-2.jpg",l="/recipes/koushui-chicken/top-3.jpg",c="/recipes/koushui-chicken/top-4.jpg",d="/recipes/koushui-chicken/step-1-a.jpg",n="/recipes/koushui-chicken/step-2-a.jpg",p="/recipes/koushui-chicken/step-3-a.jpg",g="/recipes/koushui-chicken/step-4-a.jpg",h="/recipes/koushui-chicken/step-5-a.jpg",u="/recipes/koushui-chicken/step-6-a.jpg",_="/recipes/koushui-chicken/step-7-a.jpg",k="/recipes/koushui-chicken/step-8-a.jpg",z=JSON.parse('{"title":"口水鸡","description":"小火浸煮再泡冰水，皮脆肉嫩，红油料汁一浇，撒花生碎葱花的川味凉菜做法","frontmatter":{"date":"2026-11-19T20:43:35.000Z","title":"口水鸡","description":"小火浸煮再泡冰水，皮脆肉嫩，红油料汁一浇，撒花生碎葱花的川味凉菜做法","permalink":"/pages/0eb188","categories":["life","recipes"]},"headers":[],"relativePath":"life/recipes/koushui-chicken.md","filePath":"life/recipes/koushui-chicken.md","lastUpdated":null}'),m={name:"life/recipes/koushui-chicken.md"};function f(b,t,y,j,x,q){return s(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="口水鸡" tabindex="-1">口水鸡 <a class="header-anchor" href="#口水鸡" aria-label="Permalink to &quot;口水鸡&quot;">​</a></h1><div class="recipe-gallery"><img src="'+o+'" alt="口水鸡成品：白盘里斩好的鸡块浸在红油料汁里，撒花生碎葱花芝麻香菜"><img src="'+a+'" alt="特写：鸡块裹着红油辣椒汁，挂着花生碎和葱花"><img src="'+l+'" alt="小碗里的口水鸡配白米饭，筷子平搁在碗边"><img loading="lazy" src="'+c+'" alt="原料摆拍：鸡腿、姜葱、辣椒面花椒面芝麻花生碎、黄瓜条"></div><p>口水鸡是凉菜，功夫全在两头：煮鸡要小火浸、不翻滚，煮完趁热泡冰水，皮才脆；料汁靠鸡汤调，红油炝香，咸鲜麻辣里带一点酸甜。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>鸡腿</td><td>两只，带皮；三黄鸡半只也行，浸煮后皮脆肉嫩</td></tr><tr><td>黄瓜</td><td>半根，切条垫底解腻</td></tr><tr><td>生姜</td><td>几片，煮鸡用</td></tr><tr><td>小葱</td><td>几根，煮鸡和最后撒料</td></tr></tbody></table><p><strong>配料与调料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>辣椒面</td><td>二荆条提香、小米辣提辣，怕辣就减小米辣</td></tr><tr><td>花椒面</td><td>一小勺，麻味来源</td></tr><tr><td>蒜末</td><td>三瓣，切末</td></tr><tr><td>姜末</td><td>少许</td></tr><tr><td>熟芝麻</td><td>一勺</td></tr><tr><td>花生碎</td><td>一勺，最后撒</td></tr><tr><td>生抽</td><td>调味主力</td></tr><tr><td>香醋</td><td>一勺，提鲜解腻</td></tr><tr><td>白糖</td><td>一小撮，中和辣味</td></tr><tr><td>香油</td><td>一勺</td></tr><tr><td>鸡汤</td><td>两勺，煮鸡的原汤，调汁用</td></tr><tr><td>料酒</td><td>煮鸡用</td></tr><tr><td>葱花、香菜</td><td>最后撒</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>泡血水。</strong> 鸡腿冷水泡 20 分钟，中途换一次水，泡到水不再发红。</p><figure class="recipe-shots"><img loading="lazy" src="'+d+'" alt="鸡腿泡在冷水里，水面带浅血色"></figure></li><li><p><strong>小火浸煮。</strong> 鸡腿冷水下锅，加姜、葱、料酒，大火烧开转最小火，保持汤面微开浸煮 15 分钟，关火再焖 5 分钟。别大火滚，滚出来的皮裂肉柴。</p><figure class="recipe-shots"><img loading="lazy" src="'+n+'" alt="鸡腿在温水中小火浸煮，汤面只冒小泡"></figure></li><li><p><strong>泡冰水。</strong> 捞出立刻泡冰水，镇 15 分钟。趁热泡才有温差，皮收紧发脆、肉也嫩；凉透了再泡起不来。</p><figure class="recipe-shots"><img loading="lazy" src="'+p+'" alt="煮好的鸡腿泡在冰水里，水里飘着碎冰"></figure></li><li><p><strong>斩块摆盘。</strong> 沥干斩成小块，盘底垫黄瓜条，鸡块码上去。</p><figure class="recipe-shots"><img loading="lazy" src="'+g+'" alt="斩好的鸡块码在垫了黄瓜的盘里"></figure></li><li><p><strong>备料。</strong> 蒜末、姜末、葱花、辣椒面、花椒面、熟芝麻分小碟备好。</p><figure class="recipe-shots"><img loading="lazy" src="'+h+'" alt="几小碟备好的姜蒜葱花辣椒面花椒面芝麻"></figure></li><li><p><strong>炝红油。</strong> 辣椒面、花椒面放碗里，热油浇下去炝出香味，红油把辣椒粉浸润成暗红色。油别烧冒烟，冒烟就把辣椒面浇糊了。</p><figure class="recipe-shots"><img loading="lazy" src="'+u+'" alt="热油浇进辣椒面花椒面，红油冒起热气"></figure></li><li><p><strong>调汁。</strong> 加生抽、香醋、白糖、香油、两勺鸡汤搅匀，尝一下咸淡。料汁用鸡汤调，比用水调鲜。</p><figure class="recipe-shots"><img loading="lazy" src="'+_+'" alt="小碗里调好的红油料汁，表面浮着辣椒芝麻葱花"></figure></li><li><p><strong>淋汁撒料。</strong> 料汁浇在鸡块上，撒花生碎、葱花、芝麻和香菜段。拌好尽快上桌，放久了皮回软、料汁发咸。</p><figure class="recipe-shots"><img src="'+k+'" alt="料汁浇上鸡块，撒花生碎、芝麻和香菜"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>小火浸煮不翻滚</strong>：大火滚出来的鸡皮裂、肉柴，汤面微开就够。</li><li><strong>趁热泡冰水</strong>：温差让皮收紧，口感脆弹；凉透再泡起不来。</li><li><strong>料汁用鸡汤调</strong>：比用水调鲜，别直接浇纯酱油。</li><li><strong>辣椒面分两种</strong>：二荆条香、小米辣辣，按吃辣程度配。</li><li><strong>现拌现吃</strong>：放久了皮回软、料汁发咸，拌好尽快上桌。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">偷懒版</p><p>直接买现成红油辣子，省去炝油步骤；没有鸡汤就用凉白开兑一点生抽，味道差一截但能做。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">常见翻车</p><p></p><ul><li><strong>肉柴发紧</strong>：火太大煮滚了，或者煮完没泡冰水。</li><li><strong>皮软不脆</strong>：冰水镇的时间不够，或者放久了没吃。</li><li><strong>料汁发苦</strong>：花椒面放多了，或者热油把辣椒面浇糊了。</li><li><strong>只有咸味</strong>：缺了香醋和糖，味型压不住辣。</li><li><strong>鸡肉有腥味</strong>：血水没泡净，煮鸡时姜葱料酒没放够。</li></ul></div><p><a href="/life/recipes/">← 回菜谱总览</a></p>',15)])])}const P=i(m,[["render",f]]);export{z as __pageData,P as default};
